const BEE_PROFILES = {
  bartholomew: { ceremony: 0.8, spectacle: 0.7, reassurance: 0.6, value: 0.3, chaos: 0.2, sentiment: 0.4 },
  martin: { ceremony: 0.2, spectacle: 0.1, reassurance: 0.3, value: 0.9, chaos: 0.1, sentiment: 0.2 },
  lucifer: { ceremony: 0.3, spectacle: 0.8, reassurance: 0.1, value: 0.2, chaos: 0.9, sentiment: 0.1 },
  myshkin: { ceremony: 0.4, spectacle: 0.2, reassurance: 0.7, value: 0.4, chaos: 0.1, sentiment: 0.9 },
  spinoza: { ceremony: 0.5, spectacle: 0.3, reassurance: 0.5, value: 0.5, chaos: 0.2, sentiment: 0.6 },
  gerald: { ceremony: 0.4, spectacle: 0.3, reassurance: 0.5, value: 0.5, chaos: 0.3, sentiment: 0.4 }
};

class HiveActivityEngine {
  constructor(options = {}) {
    this.minSwapMs = options.minSwapMs || 2100;
    this.maxSwapMs = options.maxSwapMs || 4800;
    this.recentWindow = options.recentWindow || 8;
    this.recent = [];
    this.lastShownAt = new Map();
    this.currentEntry = null;
  }

  select(context) {
    const phase = context.phase || 'generic';
    const bee = context.bee || 'bartholomew';
    const season = context.season || null;
    const hooks = context.hooks || {};
    
    // Build pool: base + seasonal additions
    let pool = [...HIVE_STATUSES];
    if (season && SEASONAL_ADDITIONS[season]) {
      pool = pool.concat(SEASONAL_ADDITIONS[season]);
    }
    
    // Filter by phase
    pool = pool.filter(e => e.phases.includes(phase) || e.phases.includes('generic'));
    
    // Apply bee personality weighting
    const profile = BEE_PROFILES[bee] || BEE_PROFILES.gerald;
    pool = pool.map(e => {
      let weight = e.weight;
      if (e.tags && e.tags.includes('calm') && profile.reassurance > 0.5) weight *= 1.3;
      if (e.tags && e.tags.includes('excited') && profile.spectacle > 0.5) weight *= 1.3;
      if (e.tags && e.tags.includes('chaotic') && profile.chaos > 0.5) weight *= 1.5;
      if (e.tags && e.tags.includes('sentimental') && profile.sentiment > 0.5) weight *= 1.3;
      return { ...e, weight };
    });
    
    // Apply cooldowns
    const now = Date.now();
    pool = pool.filter(e => {
      const last = this.lastShownAt.get(e.id) || 0;
      const cooldown = e.cooldownMs || 30000;
      return (now - last) > cooldown;
    });
    
    // Apply recency penalty
    pool = pool.map(e => {
      const recency = this.recent.indexOf(e.id);
      if (recency >= 0) return { ...e, weight: e.weight * (1 - recency / this.recentWindow) };
      return e;
    });
    
    // Weighted random pick
    const totalWeight = pool.reduce((sum, e) => sum + e.weight, 0);
    if (totalWeight === 0) return { text: "Working…", motionCue: "idle" };
    
    let r = Math.random() * totalWeight;
    for (const entry of pool) {
      r -= entry.weight;
      if (r <= 0) {
        this.recent.push(entry.id);
        if (this.recent.length > this.recentWindow) this.recent.shift();
        this.lastShownAt.set(entry.id, now);
        this.currentEntry = entry;
        
        let text = entry.text;
        if (hooks.hook && text.includes('…')) {
          text = text.replace('…', ' ' + hooks.hook + '…');
        }
        
        return { text, motionCue: entry.motionCue, entryId: entry.id };
      }
    }
    
    return { text: "Working…", motionCue: "idle" };
  }

  nextDelay() {
    if (!this.currentEntry) return 3000;
    const min = this.currentEntry.minDurationMs || this.minSwapMs;
    const max = this.currentEntry.maxDurationMs || this.maxSwapMs;
    return min + Math.random() * (max - min);
  }
}

export { HiveActivityEngine, HIVE_STATUSES, SEASONAL_ADDITIONS, BEE_PROFILES };
